const calData = $input.first().json;
const body = $('Webhook').first().json.body || {};
const action = body.action || 'list';

const now = new Date();
const events = calData.events || [];
const tasks = calData.tasks || [];
const meds = calData.meds || [];
const bills = calData.bills || [];

// Filter upcoming events (next 7 days)
const weekFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
const upcoming = events.filter(e => {
  const d = new Date(e.date || e.start);
  return d >= now && d <= weekFromNow;
}).sort((a, b) => new Date(a.date || a.start) - new Date(b.date || b.start));

// Overdue tasks
const overdue = tasks.filter(t => {
  if (t.status === 'done') return false;
  const due = new Date(t.due);
  return due < now;
});

// Meds due today
const medsToday = meds.filter(m => {
  if (!m.nextDose) return true;
  const next = new Date(m.nextDose);
  return next.toDateString() === now.toDateString();
});

// Bills due within 7 days
const billsDue = bills.filter(b => {
  if (b.status === 'paid') return false;
  const due = new Date(b.due);
  return due >= now && due <= weekFromNow;
});

return {
  json: {
    action: action,
    date: now.toISOString(),
    upcoming_events: upcoming,
    overdue_tasks: overdue,
    meds_today: medsToday,
    bills_due: billsDue,
    summary: {
      events_this_week: upcoming.length,
      overdue_tasks: overdue.length,
      meds_due: medsToday.length,
      bills_due: billsDue.length
    },
    family: calData.family || []
  }
};
